<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import { api, items, setCsrf, ApiError } from './api';
import { EventFeed } from './events';
import { forms, type Field } from './forms';
import EntityForm from './EntityForm.vue';
import TechnicalDetails from './TechnicalDetails.vue';
import { errorText, label, riskText, roleText, scalar, statusText, testOutcome } from './present';
import V11Center from './V11Center.vue';
import MemoryPolicy from './MemoryPolicy.vue';
const pages = [{id:'dashboard',label:'总览'},{id:'chat',label:'对话'},{id:'tasks',label:'任务中心'},{id:'automations',label:'自动化'},{id:'memories',label:'长期记忆'},{id:'migrations',label:'数据迁移'},{id:'apps',label:'应用中心'},{id:'providers',label:'模型与预算'},{id:'channels',label:'消息通道'},{id:'tools',label:'工具与技能'},{id:'approvals',label:'审批'},{id:'system',label:'系统'},{id:'settings',label:'设置'}];
const page=ref('dashboard'), initialized=ref(true), authenticated=ref(false), booting=ref(true), loading=ref(false), busy=ref(false), error=ref(''), notice=ref(''), username=ref('');
const data=ref<any>(null), rows=ref<any[]>([]), secondary=ref<any[]>([]), selected=ref<any>(null), messages=ref<any[]>([]), live=ref<any>(null), history=ref<any[]>([]), editor=ref<{resource:string;initial?:any}|null>(null), query=ref(''), status=ref(''), source=ref(''), date=ref(''), scope=ref(''), kind=ref(''), text=ref(''), subpage=ref('schedules'), preview=ref<any[]>([]), expression=ref(''), timezone=ref(Intl.DateTimeFormat().resolvedOptions().timeZone), cronMode=ref('advanced'), cronMinute=ref('30'), cronHour=ref('8'), cronWeekday=ref('*');
const errorDetail=ref<any>(null), connectionResult=ref<{row:any;kind:'provider'|'channel';result:any}|null>(null);
const eventState=ref('未连接'), cursor=ref(sessionStorage.getItem('hda-cursor') ?? '0');
let stream:EventFeed|undefined, refreshTimer:ReturnType<typeof setInterval>|undefined, reloadTimer:ReturnType<typeof setTimeout>|undefined, generation=0, messageGeneration=0;
const authFields=computed<Field[]>(()=>[{key:'username',label:'管理员用户名',required:true},{key:'password',label:'密码',type:'password',required:true,minLength:initialized.value?undefined:12,help:initialized.value?undefined:'至少 12 个字符，用于管理员登录。'},...(!initialized.value?[{key:'timezone',label:'IANA 时区',required:true},{key:'vendor',label:'模型提供商',options:['openai'],required:true,help:'OpenAI 兼容服务也选择 openai；服务地址填写在下面。'},{key:'baseUrl',label:'API 地址（可选）',type:'url',help:'例如 https://magpie.woyin.me/v1；留空使用 OpenAI 官方接口。自定义地址使用 Chat Completions 协议。'},{key:'model',label:'模型 ID',required:true,help:'填写服务商给出的完整模型名，例如 gpt-4.1-mini 或其他兼容名称。'},{key:'apiKey',label:'模型密钥',type:'password',required:true},{key:'telegramToken',label:'Telegram Token（可跳过）',type:'password'},{key:'allowedUsers',label:'Telegram 允许用户 ID（逗号分隔）'}]:[])]);
const authInitial=computed(()=>({timezone:timezone.value,vendor:'openai'}));
const title=computed(()=>pages.find(p=>p.id===page.value)?.label ?? '控制台');
const dashboardData=computed(()=>Object.fromEntries(Object.entries(data.value??{}).filter(([key])=>!['usageToday','channels'].includes(key))));
const editorInitial=computed(()=>editor.value?.initial ?? {timezone:timezone.value,expression:expression.value});
const resource=computed(()=>page.value==='chat'?'conversations':page.value==='automations'?subpage.value:page.value);
function report(e:unknown) { if(e instanceof ApiError && e.status===401){ authenticated.value=false; stream?.close(); } if(e instanceof ApiError){ error.value=errorText(e.code); errorDetail.value={code:e.code,status:e.status,requestId:e.requestId}; } else { error.value=e instanceof Error?e.message:String(e); errorDetail.value=null; } }
async function operation(fn:()=>Promise<void>) { if(busy.value)return; busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){report(e);}finally{busy.value=false;} }
async function boot() { try{ const setup=await api('setup/status'); initialized.value=setup.initialized; if(initialized.value){try{ const session=await api('auth/session');username.value=session.username;setCsrf(session.csrf);authenticated.value=true; await load();connect(); }catch(e){if(!(e instanceof ApiError && e.status===401))throw e;}} }catch(e){report(e);}finally{booting.value=false;} }
async function login(value:Record<string,any>) { await operation(async()=>{ const payload=initialized.value?value:{username:value.username,password:value.password,timezone:value.timezone,provider:{vendor:value.vendor,model:value.model,apiKey:value.apiKey,...(value.baseUrl?{baseUrl:value.baseUrl}:{}),...(value.contextWindow?{contextWindow:Number(value.contextWindow)}:{}),...(value.maxTokens?{maxTokens:Number(value.maxTokens)}:{})},...(value.telegramToken?{telegram:{token:value.telegramToken,allowedUsers:String(value.allowedUsers??'').split(',').map(v=>v.trim()).filter(Boolean)}}:{})};const session=await api(initialized.value?'auth/login':'setup','POST',payload);setCsrf(session.csrf);username.value=session.username;initialized.value=true;authenticated.value=true;await load();connect(); }); }
async function logout(){await operation(async()=>{await api('auth/logout','POST',{});generation++;messageGeneration++;if(reloadTimer)clearTimeout(reloadTimer);authenticated.value=false;setCsrf('');stream?.close();sessionStorage.removeItem('hda-cursor');cursor.value='0';rows.value=[];data.value=null;messages.value=[];});}
function go(id:string){page.value=id;data.value=null;rows.value=[];secondary.value=[];selected.value=null;editor.value=null;query.value='';status.value='';source.value='';date.value='';history.value=[];void load();}
async function load(quiet=false){ if(!authenticated.value)return;const token=++generation;if(!quiet)loading.value=true;error.value='';try{const p=page.value;let result:any,extra:any[]=[];
 if(p==='dashboard')result=await api('system/summary');
 else if(p==='system'){const values=await Promise.all([api('system'),api('system/audit'),api('system/logs'),api('backups')]);result=values[0];extra=[{label:'审计流水',items:items(values[1])},{label:'运行日志',items:items(values[2])},{label:'备份',items:items(values[3])}];}
 else if(p==='settings'){const values=await Promise.all([api('settings'),api('settings/history')]);result=values[0];extra=items(values[1]);}
 else if(p==='migrations'||p==='apps')result=null;
 else {const params=new URLSearchParams();if(query.value)params.set(p==='memories'?'q':'search',query.value);if(status.value)params.set('status',status.value);if(source.value)params.set('source',source.value);if(date.value)params.set('date',date.value);if(scope.value)params.set('scope',scope.value);if(kind.value)params.set('kind',kind.value); result=await api(resource.value+(params.size?'?'+params:''));if(p==='tools')extra=items(await api('skills'));}
 if(token!==generation)return;data.value=result;rows.value=items(result).filter(row=>{if(query.value&&!JSON.stringify(row).toLocaleLowerCase().includes(query.value.toLocaleLowerCase()))return false;if(scope.value&&row.scope!==scope.value)return false;if(kind.value&&row.kind!==kind.value)return false;if(date.value){const at=row.createdAt??row.created_at;if(!at||new Date(at).toISOString().slice(0,10)!==date.value)return false;}return true;});secondary.value=extra;
 if(selected.value){if(p==='tasks')selected.value=await api('tasks/'+encodeURIComponent(selected.value.id));else if(p==='chat')await loadMessages();}
 }catch(e){if(token===generation)report(e);}finally{if(token===generation)loading.value=false;}}
async function open(row:any){selected.value=row;history.value=[];await operation(async()=>{if(page.value==='tasks')selected.value=await api('tasks/'+encodeURIComponent(row.id));if(page.value==='chat'){await loadMessages();}if(page.value==='automations')history.value=items(await api(subpage.value+'/'+encodeURIComponent(row.id)+'/history'));if(page.value==='memories')history.value=items(await api('memories/'+encodeURIComponent(row.id)+'/revisions'));});}
async function loadMessages(){if(!selected.value)return;const conversationId=selected.value.id, id=encodeURIComponent(conversationId), token=++messageGeneration;const [result,current,tasks]=await Promise.all([api('conversations/'+id+'/messages'),api('conversations/'+id+'/live'),api('tasks?conversationId='+id)]);if(page.value!=='chat'||selected.value?.id!==conversationId||token!==messageGeneration)return;const active=items(tasks).filter(task=>task.conversationId===conversationId&&!['SUCCEEDED','FAILED','CANCELLED'].includes(task.status));const task=active.find(task=>['RUNNING','WAITING_APPROVAL','PAUSED'].includes(task.status))??active[0];selected.value={...selected.value,activeTaskId:task?.id};messages.value=items(result).slice().reverse();live.value=current;}
function edit(resourceName:string,row?:any){editor.value={resource:resourceName,initial:row};preview.value=[];}
async function save(value:Record<string,any>){await operation(async()=>{const e=editor.value;if(!e)return;if(e.resource==='conversations'&&!e.initial?.id)delete value.status;if(e.resource==='memories'&&value.expiresAt)value.expiresAt=new Date(value.expiresAt).toISOString();if(e.resource==='conversations'&&e.initial?.id)delete value.model;if(e.resource==='channels'&&typeof value.allowedUsers==='string')value.allowedUsers=value.allowedUsers.split(',').map(v=>v.trim()).filter(Boolean);if(e.resource==='providers'){if(value.baseUrl===undefined)value.baseUrl='';for(const key of ['contextWindow','maxTokens','inputPrice','outputPrice'])if(value[key]===undefined)value[key]=null;};if(e.resource==='schedules')await api('schedules/preview?'+new URLSearchParams({expression:value.expression,timezone:value.timezone}));await api(e.resource+(e.initial?.id?'/'+encodeURIComponent(e.initial.id):''),e.initial?.id||e.resource==='settings'?'PATCH':'POST',value);editor.value=null;notice.value='保存成功，已重新读取服务端状态。';await load();});}
async function action(resourceName:string,row:any,actionName:string){if(!window.confirm(`确认对“${row.name??row.id}”执行“${actionName}”？已执行的外部操作不会自动撤销。`))return;await operation(async()=>{await api(resourceName+'/'+encodeURIComponent(row.id)+'/actions','POST',{action:actionName});notice.value='操作已由服务端受理。';await load();});}
async function remove(resourceName:string,row:any){if(!window.confirm(`确认删除“${row.name??row.id}”？`))return;await operation(async()=>{await api(resourceName+'/'+encodeURIComponent(row.id),'DELETE');if(selected.value?.id===row.id)selected.value=null;await load();notice.value='已删除。';});}
async function test(resourceName:string,row:any){await operation(async()=>{const result=await api(resourceName+'/'+encodeURIComponent(row.id)+'/test','POST',{});const outcome=testOutcome(resourceName==='channels'?'channel':'provider',result);connectionResult.value={row,kind:resourceName==='channels'?'channel':'provider',result};notice.value=`${outcome.title}：${outcome.detail}`;await load();});}
async function toggle(resourceName:string,row:any){if(!window.confirm(`确认${row.enabled?'停用':'启用'}“${row.name??row.id}”？此变更影响后续运行。`))return;await operation(async()=>{await api(resourceName+'/'+encodeURIComponent(row.id),'PATCH',{enabled:!row.enabled});await load();notice.value='已更新启用状态。';});}
async function decide(row:any,decision:string){if(!window.confirm(`确认${decision==='APPROVED'?'批准本次确切操作':'拒绝操作'}？请先核对对象、风险、参数和有效期。`))return;await operation(async()=>{await api('approvals/'+encodeURIComponent(row.id)+'/decisions','POST',{decision,operationHash:row.operationHash});await load();notice.value='审批决定已提交。';});}
async function send(){if(!text.value.trim()||!selected.value)return;await operation(async()=>{await api('conversations/'+encodeURIComponent(selected.value.id)+'/messages','POST',{content:text.value});text.value='';await loadMessages();notice.value='消息已提交。忙碌会话由服务端按队列策略处理。';});}
async function cronPreview(){await operation(async()=>{const expr=cronMode.value==='advanced'?expression.value:`${cronMinute.value} ${cronHour.value} * * ${cronWeekday.value}`;expression.value=expr;const result=await api('schedules/preview?'+new URLSearchParams({expression:expr,timezone:timezone.value}));preview.value=items(result.times??result.runs??result);notice.value='已从服务端取得运行预览。';});}
function connect(){stream?.close();if(!authenticated.value)return;stream=new EventFeed({cursor:()=>cursor.value,state:value=>{eventState.value=value;},refresh:()=>{if(reloadTimer)clearTimeout(reloadTimer);reloadTimer=setTimeout(()=>void load(true),200);},event:(id)=>{cursor.value=id;sessionStorage.setItem('hda-cursor',id);},reset:()=>{cursor.value='0';sessionStorage.removeItem('hda-cursor');},unauthorized:()=>{authenticated.value=false;}});stream.start();}
async function confirmDelivery(row:any,delivered:boolean){if(!window.confirm(delivered?'确认已通过平台核对消息已送达？':'确认已通过平台核对消息未送达？此操作只记录人工确认，不自动重发。'))return;await operation(async()=>{await api('channels/'+encodeURIComponent(row.channelId)+'/outbox/'+encodeURIComponent(row.id)+'/confirm','POST',{confirm:true,delivered});await load();notice.value='投递核对结果已保存。';});}
const labels:Record<string,string>={adapter:'适配器状态',maintenance:'维护模式',diskLow:'磁盘低水位',readOnly:'保护模式',runningTasks:'运行任务',queueDepth:'排队任务',pendingApprovals:'待审批',providers:'模型状态',rss:'进程内存（字节）',schemaVersion:'数据库版本',piVersion:'Pi 版本',lastError:'最近错误',usage:'用量',channels:'消息通道',todayTokens:'今日 Token',todayCost:'今日估算成本',version:'应用版本'};
function messageText(entry:any):string {if(entry.model)return entry.model.flatMap((message:any)=>typeof message.content==='string'?[message.content]:(message.content??[]).filter((block:any)=>block.type==='text').map((block:any)=>block.text)).join('\n');return display(entry.content??entry.text??entry.answerText??entry.data);}
function display(value:any):string {if(value===null||value===undefined)return '未提供';if(typeof value==='boolean')return value?'是':'否';if(typeof value==='object')return JSON.stringify(value,(key,v)=> /^(apiKey|token|secret|password|authorization|cookie)$/i.test(key)?'已隐藏':v,2);return String(value);}
function expired(row:any){const expiry=typeof row.expiresAt==='number'?row.expiresAt:new Date(row.expiresAt).getTime();return row.status!=='PENDING'||!Number.isFinite(expiry)||expiry<=Date.now();}
const backupPassword=ref(''),backupId=ref(''),currentPassword=ref(''),newPassword=ref('');
async function backup(restore=false){if(!window.confirm(restore?'恢复将覆盖当前会话、任务、记忆和配置。服务端须先备份当前状态。确认继续？':'确认创建包含私人数据的备份？下载后请妥善保存。'))return;await operation(async()=>{const result=await api(restore?'restore':'backup','POST',{ password:backupPassword.value,confirm:true,...(restore?{backupId:backupId.value}:{})});backupPassword.value='';notice.value=(restore?'恢复结果：':'备份结果：')+display(result);await load();});}
async function download(path:string,filename:string){await operation(async()=>{const value=await api(path);const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
async function changePassword(){await operation(async()=>{await api('auth/password','POST',{current:currentPassword.value,next:newPassword.value});currentPassword.value='';newPassword.value='';authenticated.value=false;setCsrf('');stream?.close();notice.value='密码已修改，请重新登录。';});}
onMounted(()=>{void boot();refreshTimer=setInterval(()=>{if(authenticated.value&&!busy.value&&!editor.value)void load(true);},10000);});onBeforeUnmount(()=>{stream?.close();if(refreshTimer)clearInterval(refreshTimer);if(reloadTimer)clearTimeout(reloadTimer);});
</script>

<template>
<a class="skip" href="#content">跳到主内容</a>
<div v-if="booting" class="auth" role="status">正在检查初始化与登录状态…</div>
<main v-else-if="!authenticated" id="content" class="auth">
 <h1>{{initialized?'登录家庭 Agent':'首次配置家庭 Agent'}}</h1><p v-if="!initialized">服务仅在容器内运行。默认拒绝宿主机与高危操作。请配置管理员、时区和模型。Telegram 可稍后添加。</p>
 <p v-if="error" class="error" role="alert">{{error}}</p><EntityForm :fields="authFields" :initial="authInitial" :busy="busy" :submit-label="initialized?'登录':'完成配置'" @submit="login" />
</main>
<div v-else class="shell">
 <aside><h1>家庭 Agent</h1><nav aria-label="主导航"><button v-for="p in pages" :key="p.id" :aria-current="page===p.id?'page':undefined" @click="go(p.id)">{{p.label}}</button></nav><p>{{username}}</p><button :disabled="busy" @click="logout">注销会话</button></aside>
 <main id="content" tabindex="-1"><header><div><h2>{{title}}</h2><small role="status">事件流：{{eventState}} · 游标 {{cursor}}</small></div><button :disabled="loading" @click="load()">刷新</button></header>
 <p v-if="error" class="error" role="alert">{{error}} <button @click="load()">重试读取</button></p><TechnicalDetails v-if="errorDetail" :value="errorDetail" label="错误技术详情" /><p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="loading" role="status">正在读取服务端数据…</p>
 <section v-if="editor" class="editor" aria-label="编辑表单"><h3>{{editor.initial?'编辑':'新增'}}{{editor.resource}}</h3><button class="secondary" @click="editor=null">关闭编辑</button><EntityForm :fields="forms[editor.resource] ?? []" :initial="editorInitial" :busy="busy" @submit="save" /></section>
 <V11Center v-if="page==='migrations'||page==='apps'" :key="page" :kind="page==='migrations'?'migrations':'apps'" />
 <template v-else-if="page==='dashboard'"><p v-if="!data&&!loading">数据不可用。请检查服务状态并重试。</p><div v-else-if="data" class="cards"><article><h3>今日用量</h3><p>UTC 日期：{{display(data.usageToday?.day)}}</p><p>Token：{{display(data.usageToday?.tokens)}}</p><p>估算成本：{{display(data.usageToday?.cost)}}</p><p v-if="data.usageToday?.unknownCost">部分成本未知，含未结算项目的预留估价，并非实际结算金额。</p></article><article><h3>消息通道</h3><p v-if="!data.channels?.length">暂无通道。</p><div v-for="channel in data.channels" :key="channel.id"><p>{{channel.name}}（{{channel.id}}） · {{display(channel.status)}}</p><p>最近错误：{{display(channel.lastError)}}</p></div></article><article v-for="(value,key) in dashboardData" :key="key"><h3>{{labels[String(key)]??key}}</h3><template v-if="value&&typeof value==='object'"><TechnicalDetails :value="value" :label="labels[String(key)]??key" /></template><p v-else>{{scalar(value,String(key))}}</p></article></div></template>
 <template v-else-if="page==='settings'"><EntityForm v-if="data" :fields="forms.settings" :initial="data" :busy="busy" @submit="value=>{editor={resource:'settings',initial:data};save(value)}" /><section><h3>系统指令版本历史</h3><p v-if="!secondary.length">暂无历史。</p><article v-for="revision in secondary" :key="revision.id"><h4>版本 {{revision.version}}</h4><p>保存时间：{{new Date(revision.at).toLocaleString()}}</p><pre>{{revision.content}}</pre></article></section><section><h3>修改密码</h3><form class="fields" @submit.prevent="changePassword"><label>当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" required></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="12" required></label><button :disabled="busy">修改密码</button></form></section></template>
 <template v-else-if="page==='system'"><div class="cards"><article v-for="(value,key) in data" :key="key"><h3>{{labels[String(key)]??key}}</h3><template v-if="value&&typeof value==='object'"><TechnicalDetails :value="value" :label="labels[String(key)]??key" /></template><p v-else>{{scalar(value,String(key))}}</p></article></div><section v-for="group in secondary" :key="group.label"><h3>{{group.label}}</h3><p v-if="!group.items.length">暂无记录。</p><details v-for="(row,index) in group.items" :key="row.id??index"><summary>{{row.action??row.message??row.name??row.id??index}}</summary><pre>{{display(row)}}</pre></details></section><section><h3>导出与升级</h3><button :disabled="busy" @click="download('system/diagnostics','diagnostics.json')">下载诊断 JSON</button><button :disabled="busy" @click="download('config/export','config.json')">下载配置 JSON</button><p>升级前确认目标版本和数据库版本兼容，停止外部入站并处理运行中的任务。创建并验证备份，另存主密钥，记录旧版本和镜像。升级后检查服务、登录和关键任务；失败时保全数据并使用匹配的旧版本和备份回滚。</p></section><section><h3>备份与恢复</h3><p>恢复会覆盖当前数据。恢复前服务端必须先备份当前状态。备份包含私人内容，密钥须独立管理。</p><label>管理员密码（再次认证）<input v-model="backupPassword" type="password" autocomplete="current-password"></label><button :disabled="busy||!backupPassword" @click="backup(false)">创建备份</button><label>恢复的备份 ID<input v-model="backupId"></label><button class="danger" :disabled="busy||!backupPassword||!backupId" @click="backup(true)">确认并恢复备份</button></section></template>
 <template v-else>
  <MemoryPolicy v-if="page==='memories'" />
  <button v-if="page==='memories'" :disabled="busy" @click="download('memories/export','memories.json')">导出记忆 JSON</button>
  <div v-if="page==='automations'" class="toolbar"><button @click="subpage='schedules';selected=null;load()">Cron</button><button @click="subpage='heartbeats';selected=null;load()">Heartbeat</button></div>
  <form class="toolbar" @submit.prevent="load()"><label>搜索<input v-model="query" type="search"></label><template v-if="page==='tasks'"><label>状态<select v-model="status"><option value="">全部</option><option v-for="s in ['CREATED','QUEUED','RUNNING','WAITING_APPROVAL','RETRY_WAIT','PAUSED','SUCCEEDED','FAILED','CANCELLED']" :key="s">{{s}}</option></select></label><label>来源<select v-model="source"><option value="">全部</option><option>web</option><option>telegram</option><option>cron</option><option>heartbeat</option></select></label><label>日期<input v-model="date" type="date"></label></template><template v-if="page==='memories'"><label>作用域<input v-model="scope"></label><label>类型<select v-model="kind"><option value="">全部</option><option>semantic</option><option>episodic</option><option>procedural</option></select></label></template><button>查询</button><button v-if="forms[resource]" type="button" @click="edit(resource)">新增</button></form>
  <section v-if="page==='automations'&&subpage==='schedules'"><h3>Cron 运行预览</h3><div class="toolbar"><label>编辑模式<select v-model="cronMode"><option value="advanced">高级表达式</option><option value="simple">每天 / 每周</option></select></label><label v-if="cronMode==='advanced'">Cron 表达式<input v-model="expression" placeholder="30 8 * * *"></label><template v-else><label>小时<input v-model="cronHour" type="number" min="0" max="23"></label><label>分钟<input v-model="cronMinute" type="number" min="0" max="59"></label><label>星期<select v-model="cronWeekday"><option value="*">每天</option><option v-for="d in 7" :key="d" :value="String(d%7)">星期 {{d}}</option></select></label></template><label>IANA 时区<input v-model="timezone"></label><button :disabled="busy" @click="cronPreview">校验并预览五次</button></div><p>运行时间与夏令时由服务端计算。保存前再次校验表达式。</p><ol v-if="preview.length"><li v-for="(run,i) in preview" :key="i">{{display(run)}}</li></ol></section>
  <p v-if="!loading&&!rows.length" class="empty">暂无符合条件的记录。</p>
  <div class="records"><article v-for="row in rows" :key="row.id??row.name"><div class="record-head"><h3>{{row.name??row.goal??row.content??row.toolName??row.id}}</h3><span>{{row.status?statusText(row.status):(row.enabled===undefined?'':row.enabled?'已启用':'已停用')}}</span></div>
   <p v-if="row.lastError??row.last_error" class="error">{{errorText(row.lastError??row.last_error)}}</p>
   <template v-if="page==='approvals'"><dl><dt>发起任务</dt><dd>{{row.taskId}}</dd><dt>风险</dt><dd>{{riskText(row.risk)}}</dd><dt>对象与影响</dt><dd>{{display(row.summary?.target??row.summary?.impact??row.target??row.impact??row.toolName)}}</dd><dt>参数摘要</dt><dd><pre>{{display(row.argsSummary??row.summary)}}</pre></dd><dt>操作校验码</dt><dd><TechnicalDetails :value="{operationHash:row.operationHash}" label="校验码技术详情" /></dd><dt>截止时间</dt><dd>{{row.expiresAt}}</dd></dl><button :disabled="busy||expired(row)" @click="decide(row,'APPROVED')">批准本次操作</button><button class="danger" :disabled="busy||expired(row)" @click="decide(row,'REJECTED')">拒绝</button></template>
   <template v-else><button v-if="['chat','tasks','memories','automations'].includes(page)" :disabled="busy" @click="open(row)">查看详情</button><button v-if="forms[resource]" @click="edit(resource,row)">编辑</button><button v-if="['memories','providers','channels','automations'].includes(page)" class="danger" :disabled="busy" @click="remove(resource,row)">删除</button><template v-if="['providers','channels'].includes(page)"><p>凭据：{{row.configured??row.secretConfigured?'已配置':'未配置'}}</p><p v-if="row.status">连接状态：{{statusText(row.status)}}</p><button :disabled="busy" @click="test(resource,row)">测试连接</button><template v-if="connectionResult&&connectionResult.row.id===row.id"><p :class="testOutcome(connectionResult.kind,connectionResult.result).ok?'notice':'error'"><strong>{{testOutcome(connectionResult.kind,connectionResult.result).title}}</strong>：{{testOutcome(connectionResult.kind,connectionResult.result).detail}}</p><TechnicalDetails :value="connectionResult.result" label="连接测试详情" /></template></template><template v-if="page==='automations'"><button :disabled="busy" @click="toggle(resource,row)">{{row.enabled?'暂停':'恢复'}}</button><button :disabled="busy" @click="action(resource,row,'run')">立即执行</button></template><template v-if="page==='tools'"><p>影响：{{riskText(row.sideEffect??row.side_effect)||'只读'}}</p><button :disabled="busy" @click="toggle('tools',{...row,id:row.name})">{{row.enabled?'停用':'启用'}}</button></template><TechnicalDetails :value="row" label="服务端记录（技术详情）" /></template>
  </article></div>
  <section v-if="page==='tools'"><h3>受信任技能</h3><p v-if="!secondary.length">暂无技能。仅支持服务端可信目录中的技能。</p><article v-for="skill in secondary" :key="skill.id"><h4>{{skill.name}} · {{skill.version}}</h4><p>权限：{{display(skill.permissions)}}</p><details><summary>查看技能内容</summary><pre>{{skill.content}}</pre></details><button :disabled="busy" @click="toggle('skills',{...skill,id:skill.name})">{{skill.enabled?'停用':'启用'}}</button></article></section>
  <section v-if="selected" class="detail"><header><h3>{{selected.name??selected.goal??selected.id}}</h3><button @click="selected=null">关闭详情</button></header>
   <template v-if="page==='chat'"><TechnicalDetails v-if="live" :value="live" label="当前运行进度与用量（技术详情）" /><div class="messages" aria-live="polite"><p v-if="!messages.length">暂无消息。发送首条消息以创建任务。</p><article v-for="(message,i) in messages" :key="message.id??i"><strong>{{roleText(message.role??message.kind)}}</strong><p>{{messageText(message)}}</p><details v-if="message.kind?.includes('tool')||message.tools||message.toolCalls"><summary>工具执行</summary><pre>{{display(message.tools??message.toolCalls??message.data??message.model)}}</pre></details><small v-if="message.attachments">附件：{{display(message.attachments)}}</small></article></div><form class="fields" @submit.prevent="send"><p>模型在创建会话时选择。当前模型：{{selected.model??'默认模型'}}。</p><label>消息<textarea v-model="text" required rows="4"></textarea></label><button :disabled="busy||!text.trim()">发送消息</button></form><button v-if="selected.activeTaskId" class="danger" :disabled="busy" @click="action('tasks',{id:selected.activeTaskId},'cancel')">取消当前任务</button><p>附件仅展示服务端已有状态。</p></template>
   <template v-else-if="page==='tasks'"><dl><dt>状态</dt><dd>{{statusText(selected.status)}}</dd><dt>来源 / 所有者</dt><dd>{{selected.source}} / {{selected.ownerId}}</dd><dt>使用量</dt><dd>模型调用 {{scalar(selected.usage?.modelCalls)}} 次 · 工具调用 {{scalar(selected.usage?.toolCalls)}} 次</dd><dt>交付状态</dt><dd>{{display(selected.deliveries??selected.delivery??selected.outbox)}}</dd><dt>错误</dt><dd>{{selected.error?errorText(selected.error):'无'}}</dd></dl><div class="toolbar"><button v-for="a in ['pause','resume','cancel','retry']" :key="a" :disabled="busy" @click="action('tasks',selected,a)">{{({pause:'暂停',resume:'继续',cancel:'取消',retry:'重试'} as Record<string,string>)[a]}}</button></div><h4>执行时间线</h4><ol class="timeline"><li v-for="(step,i) in selected.steps??selected.timeline??[]" :key="step.id??i"><strong>{{step.kind??step.type}} · {{step.status}}</strong><p>{{step.startedAt??step.occurredAt}}</p><TechnicalDetails :value="step" label="步骤技术详情" /></li></ol><p v-if="!(selected.steps??selected.timeline)?.length">暂无执行步骤。</p><h4>交付核对</h4><article v-for="delivery in selected.deliveries??[]" :key="delivery.id"><p>{{statusText(delivery.state)}} · 通道 {{delivery.channelId}}</p><template v-if="delivery.state==='DELIVERY_UNCERTAIN'"><p>消息是否已送达尚不确定。请先到平台核对。</p><button :disabled="busy" @click="confirmDelivery(delivery,true)">核对为已送达</button><button :disabled="busy" @click="confirmDelivery(delivery,false)">核对为未送达</button></template></article><h4>外部操作记录</h4><TechnicalDetails :value="selected.operations" /><h4>关联审批</h4><TechnicalDetails :value="selected.approvals" /></template>
   <template v-else><dl v-for="(value,key) in selected" :key="key"><dt>{{label(String(key))}}</dt><dd><template v-if="value&&typeof value==='object'"><TechnicalDetails :value="value" :label="label(String(key))" /></template><span v-else>{{scalar(value,String(key))}}</span></dd></dl><h4>{{page==='memories'?'修订历史':'运行历史'}}</h4><p v-if="!history.length">暂无历史。</p><article v-for="(row,i) in history" :key="row.id??i"><TechnicalDetails :value="row" label="历史记录技术详情" /></article></template>
  </section>
 </template>
 </main>
</div>
</template>
